files.content:
html {
  block-size: 100%;
}

body {
  display: flex;
  justify-content: center;
  align-items: center;
  margin: 0;
  font-family: 'Open Sans', sans-serif;
  background: url(https://code.s3.yandex.net/web-code/images/dotted-l.svg);
  block-size: 100%;
  min-inline-size: 650px;
}

.wrapper {
  display: flex;
  gap: 60px;
  border: 1px solid #000;
  padding: 50px;
  background-color: #fff;
  max-inline-size: 850px;
}

.content {
  min-inline-size: 200px;
}

.content h2 {
  margin-block-start: 5px;
  font-size: 22px;
}

li {
  position: relative;
  margin-block-end: 10px;
  list-style: none;
}

li::before {
  content: '';
  position: absolute;
  margin-inline-end: 8px;
  border: 1px solid black;
  inset-block-start: 5px;
  inset-inline-start: -20px;
  inline-size: 12px;
  block-size: 12px;
}

li:nth-child(1)::before {
  background-color: #5f0dee;
}

li:nth-child(2)::before {
  background-color: #80d994;
}

li:nth-child(3)::before {
  background-color: #fd24af;
}

li:nth-child(4)::before {
  background-color: #6dc1fd;
}

li:nth-child(5)::before {
  background-color: #ffc802;
}

.chart {
  flex-shrink: 0;
  border-radius: 50%;
  background-image: conic-gradient( #5f0dee 15%, #80d994 15% 20%, #fd24af 20% 33%, #6dc1fd 33% 50%, #ffc802 50% );
  inline-size: 300px;
  block-size: 300px;
}
